INSERT INTO `areaclic` VALUES ('mdCircBraco','Circunferncia do brao','FITAMETRICA',NULL,'{\\rtf1\\ansi\\deff0\\deftab720{\\fonttbl{\\f0\\fswiss MS Sans Serif;}{\\f1\\froman\\fcharset2 Symbol;}{\\f2\\fswiss\\fcharset1 MS Sans Serif;}{\\f3\\fswiss\\fprq2 Arial;}{\\f4\\fswiss\\fcharset1 MS Sans Serif;}}\r\n{\\colortbl\\red0\\green0\\blue0;}\r\n\\deflang1046\\pard\\plain\\f3\\fs22\\b Circunfer\\\'eancia do bra\\\'e7o\r\n\\par \r\n\\par \\plain\\f3\\fs22 Deve ser medida com fita m\\\'e9trica inextens\\\'edvel no ponto m\\\'e9dio entre o acr\\\'f4mio da esc\\\'e1pula e o ol\\\'e9crano da ulna. Para a obten\\\'e7\\\'e3o desse ponto, o indiv\\\'edduo deve permanecer em p\\\'e9, com bra\\\'e7o fletido a 90\\\'ba e, com a fita, medir-se a dist\\\'e2ncia entre os 2 pontos citados acima, sendo que o ponto eq\\\'fcidistante deve ser marcado com uma caneta. Para se obter a CB, o indiv\\\'edduo deve relaxar o bra\\\'e7o e circundar o ser per\\\'edmetro com a fita, sem comprimir as partes moles. A leitura deve ser feita no cent\\\'edmetro mais pr\\\'f3ximo.\r\n\\par \\plain\\f4\\fs16 \r\n\\par }\r\n',8);